// pxl-tool/spec/cmd.rs

//! The core's link's bindings from spec/client/core/wit/, generated by
//! xpute-link-gen, over xpute's WIT and the GPU plugin's, as their targets
//! declare them (xpute-gen-targets, xpute-gpu-gen-targets).

use xpute_link_gen::wit::{wit_outputs, WitTarget};

use super::Output;
use crate::root;

pub fn outputs() -> Result<Vec<Output>, String> {
    let root = root();
    let xpute = root.join("xpute");
    let peers = |targets: &'static [WitTarget<'static>], gpu| -> Vec<_> {
        [&xpute_gen_targets::LINK_TARGET]
            .into_iter()
            .chain(targets)
            .chain([gpu])
            .map(|t| (xpute.as_path(), t))
            .collect()
    };
    let guest = peers(
        xpute_gen_targets::GUEST_TARGETS,
        &xpute_gpu_gen_targets::GUEST_TARGET,
    );
    let target = WitTarget {
        wit: "spec/client/core/wit",
        rs: Some("rust/client/core/src/abi.rs"),
        ts: Some("ts/client/src/abi"),
        side: "xpute/guest/rust",
    };
    wit_outputs(&root, &target, &guest)
}
